def row_description(body):
    if len(body)<2:raise ValueError('short T')
    count=struct.unpack_from('!H',body)[0];at=2;out=[]
    for _ in range(count):
        end=body.index(b'\0',at);name=body[at:end].decode();at=end+1
        if len(body)-at<18:raise ValueError('short T field')
        out.append([name,*struct.unpack_from('!IhIhih',body,at)]);at+=18
    if at!=len(body):raise ValueError('T tail')
    return out


def decode(raw):
    result=dict(rows=[],descriptors=[],tags=[],errors=[],ready=[])
    for frame in raw:
        kind=frame['kind'];body=bytes.fromhex(frame['body_hex'])
        if kind=='T':result['descriptors'].append(row_description(body))
        elif kind=='D':
            if len(body)<2:raise ValueError('short D')
            n=struct.unpack_from('!H',body)[0];at=2;row=[]
            for _ in range(n):
                if len(body)-at<4:raise ValueError('short D length')
                length=struct.unpack_from('!i',body,at)[0];at+=4
                if length < -1 or length>len(body)-at:raise ValueError('D span')
                row.append(None if length==-1 else body[at:at+length].decode())
                if length>=0:at+=length
            if at!=len(body):raise ValueError('D tail')
            result['rows'].append(row)
        elif kind=='C':
            if not body.endswith(b'\0') or b'\0' in body[:-1]:raise ValueError('C tail')
            result['tags'].append(body[:-1].decode())
        elif kind=='E':
            at=0;fields={}
            while at<len(body) and body[at]:
                key=chr(body[at]);at+=1;end=body.index(b'\0',at);fields[key]=body[at:end].decode();at=end+1
            if at!=len(body)-1 or body[at:]!=b'\0':raise ValueError('E tail')
            result['errors'].append(fields)
        elif kind=='Z':
            if len(body)!=1 or body not in (b'I',b'T',b'E'):raise ValueError('Z body')
            result['ready'].append(body.decode())
    if len(result['ready'])!=1 or not raw or raw[-1]['kind']!='Z':raise ValueError('one final Ready required')
    result['state']=result['errors'][-1].get('C') if result['errors'] else None
    return result


class Receiver:
    def __init__(self,client,sock,trace):
        self.client=client;self.sock=sock;self.trace=trace;self.roles=set();self.origins={};self.sequence=0
    def save(self):
        if self.trace.get('_save'):self.trace['_save']()
    def request(self,sql,name,target):
        event=dict(name=name,sql=sql,raw=[],complete=False);target.append(event);self.save()
        request=self.client.typed(b'Q',sql.encode()+b'\0');event['request_hex']=request.hex();wire=bytearray()
        sock=self.sock
        class Capture:
            def recv(self,n):
                data=sock.recv(n);wire.extend(data);return data
        try:
            sock.sendall(request)
            while True:
                k,b=self.client.read_message(Capture());event['raw'].append(dict(kind=k.decode(),body_hex=b.hex()));self.save()
                if k==b'Z':break
        except BaseException:
            event['partial_wire_hex']=wire.hex();self.save();raise
        event.update(decode(event['raw']));event['response_wire_sha256']=hashlib.sha256(wire).hexdigest();event['complete']=True;self.save();return event
    def anchor(self,role):
        if role in self.origins:return self.origins[role]
        name=RELATIONS[role]
        event=self.request("SELECT oid FROM pg_catalog.pg_class WHERE relname='"+name.replace("'","''")+"'",'actual-origin-'+role,self.trace['controls'])
        if event['state'] or len(event['rows'])!=1 or len(event['rows'][0])!=1 or not event['rows'][0][0] or not event['rows'][0][0].isdigit():
            self.trace['mismatches'].append(dict(id=role,field='actual_origin_unavailable',actual=event));return None
        oid=int(event['rows'][0][0]);types=[f[3] for d in event['descriptors'] for f in d]
        if oid<=0 or types!=[26]:raise ValueError('origin must be genuine pg_class OID output')
        self.origins[role]=oid;return oid
    def run(self,action):
        missing=[r for r in action['requires'] if r not in self.roles]
        if missing:
            event=dict(id=action['id'],scope=action['scope'],sql=action['sql'],status='NOTRUN_PREREQUISITE_FAILED',missing_roles=missing,original_expected=action)
            self.trace['notrun'].append(event);self.save();return
        origins={f['origin_table']:self.anchor(f['origin_table']) for f in action['fields'] or []}
        event=self.request(action['sql'],action['id'],self.trace['observations']);event['id']=action['id'];event['scope']=action['scope'];event['expected']=action
        differences=[]
        if event['state']!=action['expected_state']:differences.append(dict(field='SQLSTATE',expected=action['expected_state'],actual=event['state']))
        if event['ready']!=[action['expected_ready']]:differences.append(dict(field='Ready',expected=action['expected_ready'],actual=event['ready']))
        if action['expected_tag'] is not None and event['tags']!=[action['expected_tag']]:differences.append(dict(field='CommandComplete',expected=[action['expected_tag']],actual=event['tags']))
        if action['expected_state'] is not None and (event['rows'] or event['tags'] or len(event['errors'])!=1):differences.append(dict(field='error_row_tag_atomicity',actual=dict(rows=event['rows'],tags=event['tags'],error_count=len(event['errors']))))
        if action['expected_rows'] is not None and event['rows']!=action['expected_rows']:differences.append(dict(field='all_values_NULL',expected=action['expected_rows'],actual=event['rows']))
        if action['fields'] is not None:
            expected=[[f['name'],origins[f['origin_table']],f['attribute'],f['oid'],f['size'],f['modifier'],f['format']] for f in action['fields']]
            if event['descriptors']!=[expected]:differences.append(dict(field='complete_T7_actual_origins',expected=expected,actual=event['descriptors']))
            if any(len(row)!=len(expected) for row in event['rows']):differences.append(dict(field='row_width',expected=len(expected)))
        event['differences']=differences;event['matches_prediction']=not differences
        if differences:self.trace['mismatches'].append(dict(id=action['id'],scope=action['scope'],differences=differences))
        if not differences:self.roles.update(action['establish'])
        self.save()


def load(name,path):
    spec=importlib.util.spec_from_file_location(name,path);m=importlib.util.module_from_spec(spec);spec.loader.exec_module(m);return m

def main():
    ap=argparse.ArgumentParser();ap.add_argument('--write-plan',type=Path);args=ap.parse_args()
    source=Path(__file__).resolve();R=next(p for p in source.parents if (p/'tests/compat/pg_diff_runner.py').is_file())
    sha=lambda p:hashlib.sha256(Path(p).read_bytes()).hexdigest()
    plan=dict(schema='P28-core142-CHECK-FK-protocol-v1',primary_actions=142,cold_actions=12,actions=CORE,cold=COLD,wire_timeout_seconds=15,source_sha256=sha(source),original159_plan_sha256=ORIGINAL159_SHA256,recorded_PG_trace_sha256=RECORDED_PG_TRACE_SHA256,recorded_oracle_sha256=RECORDED_ORACLE_SHA256,original_core136_prefix=True,reserved6_recorded_oracle_sha256=RESERVED6_ORACLE_SHA256,reserved6_actual_PG_trace_sha256=RESERVED6_PG_TRACE_SHA256,scope='Ordinary CHECK/FK only; not pg_constraint/NOT NULL/full VALIDATE command compatibility',prerequisite_failure='Explicit NOTRUN; never pass',cold_reference='Stable frozen projection rows and separately frozen two enforcement writes. Real product cold process; no claim of a PG cold reference run.')
