    trace=dict(complete=False,cohort_complete=False,observations=[],controls=[],notrun=[],mismatches=[],owners=[],params_snapshots=[],metadata_checks=[],failure=None,source_sha256=sha(source),preparation=dict(selected_scopes='core',main_actions=142,cold_actions=COLD,oracle_sha256=RECORDED_ORACLE_SHA256))
    server=None;receiver=None
    def save():(E/'trace-v1.json').write_text(json.dumps({k:v for k,v in trace.items() if k!='_save'},ensure_ascii=False,separators=(',',':'))+'\n')
    trace['_save']=save
    def owner(process,phase):
        stat=Path('/proc',str(process.pid),'stat').read_text();trace['owners'].append(dict(phase=phase,pid=process.pid,pgid=os.getpgid(process.pid),start_ticks=stat[stat.rfind(')')+2:].split()[19],cmdline_hex=Path('/proc',str(process.pid),'cmdline').read_bytes().hex()));save()
    def params(phase):
        files=[]
        for path in sorted((Path(server['dir'])/'info').rglob('*.params')):
            if path.is_symlink():raise ValueError('unexpected owned metadata symlink')
            raw=path.read_bytes();files.append(dict(path=str(path.relative_to(server['dir'])),bytes=len(raw),sha256=hashlib.sha256(raw).hexdigest(),hex=raw.hex()))
        trace['params_snapshots'].append(dict(phase=phase,files=files));save()
    def reserved_flags(phase):
        check=dict(phase=phase,kind='actual-owned-params-not-SQL-catalog',matches=False)
        if 'reserved_NV' not in receiver.roles:
            check['status']='NOTRUN_PREREQUISITE_FAILED';trace['metadata_checks'].append(check);save();return
        path=Path(server['dir'])/'info/nv_reserved.params'
        if path.is_file() and not path.is_symlink():
            raw=path.read_bytes();check.update(path='info/nv_reserved.params',bytes=len(raw),sha256=hashlib.sha256(raw).hexdigest(),hex=raw.hex())
            pairs=dict(line.split('=',1) for line in raw.decode().splitlines() if '=' in line)
            check['actual']={k:pairs.get('constraint.nv_reserved_ck.'+k) for k in ['validated','not_valid']}
            check['matches']=check['actual']==dict(validated='0',not_valid='1')
        if not check['matches']:trace['mismatches'].append(dict(id='actual-metadata-'+phase,scope='core',differences=['persisted_validated0_notvalid1'],actual=check))
