        trace['owners'][-1].update(exit=process.returncode,pid_gone=not Path('/proc',str(process.pid)).exists());save()
        if process.returncode!=0:raise RuntimeError('actual normal-stop failure; no cold retry/R15 investigation')
        process=subprocess.Popen([str(binary),'--data-dir',server['dir'],'--server',str(server['port']),'--insecure'],cwd=server['dir'],stdout=(E/'cold.stdout').open('wb'),stderr=(E/'cold.stderr').open('wb'),start_new_session=True);server['process']=process;owner(process,'cold')
